import re
from collections import Counter
from itertools import combinations, groupby
from random import Random


LIMIT = 3000
REFERENCE_LIMIT = 12
SMALL_CASES = (
    (1,),
    (3000,),
    (1, 3000),
    (3000, 3000),
    (1, 3000, 1),
    (4, 4, 3, 4),
    (1, 2, 3, 4, 5, 6, 7, 3000),
    (3000, 3000, 3000, 3000, 3000, 3000, 3000, 3000),
    (1, 2, 1, 2, 1, 2, 1, 2),
    (5, 7, 5, 7, 7, 5, 7, 7),
)


def _integer(token: str) -> int | None:
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+-").lstrip("0")
    # Every magnitude with more than four significant digits is out of bounds.
    magnitude = int(digits or "0") if len(digits) <= 4 else LIMIT + 1
    return -magnitude if token.startswith("-") else magnitude


def _heights(inp: str) -> list[int] | None:
    tokens = inp.split()
    if not tokens:
        return None
    size = _integer(tokens[0])
    if size is None or not 1 <= size <= LIMIT or len(tokens) != size + 1:
        return None
    heights = []
    for token in tokens[1:]:
        height = _integer(token)
        if height is None or not 1 <= height <= LIMIT:
            return None
        heights.append(height)
    return heights


def _format_input(heights) -> str:
    return f"{len(heights)}\n{' '.join(map(str, heights))}\n"


def _random_small(rng: Random) -> list[int]:
    size = rng.randint(1, 8)
    alphabet = rng.sample(range(1, LIMIT + 1), rng.randint(1, size))
    return rng.choices(alphabet, k=size)


def validate_input(inp: str) -> bool:
    return _heights(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = []
    for index in range(n):
        heights = (
            SMALL_CASES[index]
            if index < len(SMALL_CASES)
            else _random_small(rng)
        )
        cases.append(_format_input(heights))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    height, other, third = rng.sample(range(1, LIMIT + 1), 3)
    long_run = [height] * (LIMIT - 1) + [other]
    mixed = [height] * 1800 + [other] * 900 + [third] * 300
    rng.shuffle(mixed)
    return [_format_input(long_run), _format_input(mixed)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    heights = _heights(inp)
    if heights is None:
        return [("POST-1", "The input does not satisfy the input constraints.")]

    tokens = out.split()
    answer = _integer(tokens[0]) if len(tokens) == 1 else None
    if answer is None:
        return [("POST-2", "Expected exactly one integer token.")]

    max_frequency = max(Counter(heights).values())
    if not 1 <= answer <= max_frequency:
        return [("POST-4", f"The answer must lie in [1, {max_frequency}].")]

    longest_run = max(sum(1 for _ in run) for _, run in groupby(heights))
    lower_bound = max(longest_run, 2 if max_frequency >= 2 else 1)
    if answer < lower_bound:
        return [("POST-4", f"A qualifying selection of size {lower_bound} exists.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for index in range(n):
        heights = _random_small(rng)
        transformation = index % 3
        relation = "equal"
        if transformation == 0:
            transformed = heights[::-1]
        elif transformation == 1:
            transformed = [LIMIT + 1 - height for height in heights]
        else:
            transformed = heights + [
                rng.choice(heights) for _ in range(rng.randint(1, 4))
            ]
            relation = "le"
        pairs.append((
            "POST-5", relation, _format_input(heights), _format_input(transformed)
        ))
    return pairs


def reference_small(inp: str) -> str | None:
    heights = _heights(inp)
    if heights is None or len(heights) > REFERENCE_LIMIT:
        return None

    best = 1
    for size in range(2, len(heights) + 1):
        for indices in combinations(range(len(heights)), size):
            same_height = all(heights[i] == heights[indices[0]] for i in indices)
            gap = indices[1] - indices[0]
            equal_gaps = all(
                right - left == gap for left, right in zip(indices, indices[1:])
            )
            if same_height and equal_gaps:
                best = size
    return f"{best}\n"
